      event_type: "final_answer",
      timestamp: "2026-01-01T00:00:01Z",
      payload: { final_answer: "Done." },
      metadata: {},
      parent_event_id: null,
    };

    expect(parseTraceEvent(raw).parentEventId).toBeNull();
  });
});

